SELECT name, state, scheduled_time, completed_time, error_message
  FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY
 WHERE name = '<TASK>'
   AND scheduled_time >= DATEADD(day, -7, CURRENT_TIMESTAMP())
 ORDER BY scheduled_time DESC
 LIMIT 20;

